                  , A.WORK_ORDER_ID             AS ORG_WORK_ORDER_ID
                  , C.DUE_DATE                  AS DEMAND_DUE_DATE
                  , '-'                         AS BATCH_ORDER_ID
                  , ISNULL(A.LANE_QTY, 0)       AS LANE_QTY
                  , ISNULL(A.LANE_TACT_QTY, 0)  AS LANE_TACT_QTY
                  , A.ITEM_UOM
                  , 0                           AS SETUP_TIME
                  , 'SECOND'                    AS SETUP_TIME_UOM
                  , @V_PROC_NAME                AS INSERT_ID
                  , GETDATE()                   AS INSERT_TIME
                  , @V_PROC_NAME                AS UPDATE_ID
                  , GETDATE()                   AS UPDATE_TIME
            FROM    --SY_FP_DAILY_PRODUCTION_PLAN_R  A
                    (
                      SELECT  A.INSTANCE_ID, A.FP_PLAN_ID, 
                              A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.LINE_ID, A.OPERATION_ID, 
                              A.ITEM_ID, A.WORK_ORDER_ID,
                              A.EQUIPMENT_ID, A.PLAN_DATE, A.START_TIME, A.END_TIME, 
                              A.FIX_TYPE,
                              A.LANE_TACT_QTY AS LANE_QTY, 
                              A.LANE_TACT_QTY, 
                              A.ITEM_UOM,
                              A.WORK_ORDER_SPL_ID, 
                              A.PLAN_QTY, 
                              A.PLAN_IN_QTY, 
                              A.TOTAL_WORKING_TIME
                      FROM    SY_FP_DAILY_PRODUCTION_PLAN_R A,
                              SY_FP_PRODUCTION_PLAN_R B
                      WHERE   A.INSTANCE_ID   = @v_master_id
                      AND     A.FP_PLAN_ID    = @v_plan_id
                      AND     A.INSTANCE_ID   = B.INSTANCE_ID
                      AND     A.FP_PLAN_ID    = B.FP_PLAN_ID
                      AND     A.WORK_ORDER_ID = B.WORK_ORDER_ID
                      AND     ISNULL(B.BIN_ORDER_ID, '-') = '-'               -- BIN ORDER 가 아닌것 
                      UNION   ALL
                      SELECT  A.INSTANCE_ID, A.FP_PLAN_ID, 
                              A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.LINE_ID, A.OPERATION_ID, 
                              A.ITEM_ID, B.BIN_ORDER_ID AS WORK_ORDER_ID,
                              A.EQUIPMENT_ID, A.PLAN_DATE, A.START_TIME, A.END_TIME, 
                              A.FIX_TYPE,
                              A.LANE_TACT_QTY AS LANE_QTY, 
                              A.LANE_TACT_QTY, 
                              A.ITEM_UOM,
                              MIN(A.WORK_ORDER_SPL_ID) AS WORK_ORDER_SPL_ID, 
                              SUM(A.PLAN_QTY) AS PLAN_QTY, 
                              SUM(A.PLAN_IN_QTY) AS PLAN_IN_QTY, 
                              MIN(A.TOTAL_WORKING_TIME) AS TOTAL_WORKING_TIME
                      FROM    SY_FP_DAILY_PRODUCTION_PLAN_R A,
                              SY_FP_PRODUCTION_PLAN_R B
                      WHERE   A.INSTANCE_ID   = @v_master_id
                      AND     A.FP_PLAN_ID    = @v_plan_id
                      AND     A.INSTANCE_ID   = B.INSTANCE_ID
                      AND     A.FP_PLAN_ID    = B.FP_PLAN_ID
                      AND     A.WORK_ORDER_ID = B.WORK_ORDER_ID
                      AND     ISNULL(B.BIN_ORDER_ID, '-') != '-'               -- BIN ORDER 인 것
                      GROUP   BY 
                              A.INSTANCE_ID, A.FP_PLAN_ID, 
                              A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.LINE_ID, A.OPERATION_ID, 
                              A.ITEM_ID, B.BIN_ORDER_ID,
                              A.EQUIPMENT_ID, A.PLAN_DATE, A.START_TIME, A.END_TIME, 
                              A.FIX_TYPE,
                              A.LANE_TACT_QTY, A.ITEM_UOM                
                    ) A
                  , (
                      SELECT DISTINCT
                             A.MASTER_ID
                           , A.PLAN_ID
                           , ISNULL(B.WORK_ORDER_ID, A.PLAN_ORDER_ID) AS PLAN_ORDER_ID
                           , ISNULL(B.DEMAND_ID, A.DEMAND_ID)         AS DEMAND_ID
                           , A.ORDER_TYPE
                      FROM   TH_EXP_PLANORDER A
                             LEFT OUTER JOIN TH_MST_SCM_FIX_WORK_SPLIT B
                                  ON    A.MASTER_ID = B.MASTER_ID
                     AND   A.PLAN_ID = B.PLAN_ID
                                  AND   A.PLAN_ORDER_ID = B.SPLIT_WORK_ORDER_ID
                      WHERE  A.MASTER_ID  = @v_master_id
                      AND    A.PLAN_ID    = @v_plan_id            
                    )               B
                  , TH_DPP_NET_DEMAND              C
            WHERE   A.INSTANCE_ID   = @v_master_id
            AND     A.FP_PLAN_ID    = @v_plan_id
            AND     A.INSTANCE_ID   = B.MASTER_ID
            AND     A.FP_PLAN_ID    = B.PLAN_ID
            AND     A.WORK_ORDER_ID = B.PLAN_ORDER_ID
            AND     A.INSTANCE_ID   = C.MASTER_ID
            AND     A.FP_PLAN_ID    = C.PLAN_ID
            AND     B.DEMAND_ID     = C.NET_DEMAND_ID
            --AND     EXISTS (
            --                SELECT 1
            --                FROM   SY_SCM_OPERATION_M X
            --                WHERE  A.COMPANY_ID    = X.COMPANY_ID
            --                AND    A.DIVISION_ID   = X.DIVISION_ID
            --                AND    A.SITE_ID       = X.SITE_ID
            --                AND    A.OPERATION_ID  = X.OPERATION_ID
            --                AND    X.AMEND_FLAG    = 'Y'
            --               )
          END
        
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null
        
        
        UPDATE  SY_FP_AMEND_PRODUCTION_PLAN_R
        SET     SY_FP_AMEND_PRODUCTION_PLAN_R.MARKET = B.MARKET   -- ## 확정 MARKET 이 있을 수 있으므로 여기서 UPDATE 함.
        FROM    SY_FP_AMEND_PRODUCTION_PLAN_R A,
                SY_FP_PRODUCTION_PLAN_R B
        WHERE   A.MASTER_ID         = B.INSTANCE_ID
        AND     A.PLAN_ID           = B.FP_PLAN_ID
        AND     A.ORG_WORK_ORDER_ID = B.WORK_ORDER_ID
        AND     A.MASTER_ID         = @v_master_id
        AND     A.PLAN_ID           = @v_plan_id
          
        SET @v_message = 'MARKET : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        
        UPDATE  SY_FP_AMEND_PRODUCTION_PLAN_R
        SET     SY_FP_AMEND_PRODUCTION_PLAN_R.BATCH_ORDER_ID = B.BATCH_ORDER_ID
        FROM    SY_FP_AMEND_PRODUCTION_PLAN_R A,
                SY_FP_PRODUCTION_PLAN_R B
        WHERE   A.MASTER_ID         = B.INSTANCE_ID
        AND     A.PLAN_ID           = B.FP_PLAN_ID
        AND     A.ORG_WORK_ORDER_ID = B.WORK_ORDER_ID
        AND     B.BATCH_ORDER_ID    IS NOT NULL
        AND     B.BATCH_ORDER_ID   != '-'
        AND     A.MASTER_ID         = @v_master_id
        AND     A.PLAN_ID           = @v_plan_id
          
        SET @v_message = 'BATCH ORDER ID : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        
        UPDATE SY_FP_AMEND_PRODUCTION_PLAN_R
        SET    SY_FP_AMEND_PRODUCTION_PLAN_R.OPERATION_EPST = B.EPST
             , SY_FP_AMEND_PRODUCTION_PLAN_R.OPERATION_LPST = B.LPST
        FROM   SY_FP_AMEND_PRODUCTION_PLAN_R A,
               SY_FP_AMEND_ORDER_TRACKING B
        WHERE  A.MASTER_ID          = B.MASTER_ID
        AND    A.PLAN_ID            = B.PLAN_ID
        AND    A.ORG_WORK_ORDER_ID  = B.ORDER_ID
        AND    A.MASTER_ID         = @v_master_id
        AND    A.PLAN_ID           = @v_plan_id
        
        SET @v_message = 'EPST/LPST : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null

        UPDATE SY_FP_AMEND_PRODUCTION_PLAN_R
        SET    SY_FP_AMEND_PRODUCTION_PLAN_R.WO_DAY_SPLIT_YN = 'Y'
        FROM   SY_FP_AMEND_PRODUCTION_PLAN_R A,
               (
                SELECT ORG_WORK_ORDER_ID
                FROM   SY_FP_AMEND_PRODUCTION_PLAN_R
                WHERE  MASTER_ID         = @v_master_id
                AND    PLAN_ID           = @v_plan_id
                GROUP  BY ORG_WORK_ORDER_ID
                HAVING  COUNT(1) > 1
               ) B
        WHERE  A.MASTER_ID         = @v_master_id
        AND    A.PLAN_ID           = @v_plan_id
        AND    A.ORG_WORK_ORDER_ID = B.ORG_WORK_ORDER_ID
        
        SET @v_message = 'WO_DAY_SPLIT_YN : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null


        -- AMEND SETUP 시간 계산

        UPDATE SY_FP_AMEND_PRODUCTION_PLAN_R
        SET    SY_FP_AMEND_PRODUCTION_PLAN_R.SETUP_TIME     = B.SETUP_TIME
             , SY_FP_AMEND_PRODUCTION_PLAN_R.SETUP_TIME_UOM = 'SECOND'
        FROM   SY_FP_AMEND_PRODUCTION_PLAN_R A,
               (
                SELECT A.MASTER_ID, A.PLAN_ID,
                       A.WORK_ORDER_ID, A.AFTER_SITE_ID, A.AFTER_ROUTE_ID, A.AFTER_OPERATION_ID, A.AFTER_RESOURCE_ID, A.AFTER_PLAN_DATE, A.AFTER_SEQ, 
                       CASE WHEN SETUP_TIME_01 > 0 THEN SETUP_TIME_01
                            WHEN SETUP_TIME_02 > 0 THEN SETUP_TIME_02
                            WHEN SETUP_TIME_03 > 0 THEN SETUP_TIME_03
                            ELSE SETUP_TIME_04
                       END  SETUP_TIME
                FROM   (
                        SELECT A.*,
                               ISNULL(E.SETUP_TIME, 0) *  CASE E.SETUP_TIME_UOM WHEN 'SECOND' THEN 1
                                                                                WHEN 'MINUTE' THEN 60
                                                                                WHEN 'HOUR'   THEN 3600
                                                                                WHEN 'DAY'    THEN 86400
                                                                                              ELSE 60
                                                          END AS SETUP_TIME_01,
                               ISNULL(F.SETUP_TIME, 0) *  CASE F.SETUP_TIME_UOM WHEN 'SECOND' THEN 1
                                                                                WHEN 'MINUTE' THEN 60
                                                                                WHEN 'HOUR'   THEN 3600
                                                                                WHEN 'DAY'    THEN 86400
                                                                                              ELSE 60
                                                          END AS SETUP_TIME_02,
                               ISNULL(G.SETUP_TIME, 0) *  CASE G.SETUP_TIME_UOM WHEN 'SECOND' THEN 1
                                                                                WHEN 'MINUTE' THEN 60
                                                                                WHEN 'HOUR'   THEN 3600
                                                                                WHEN 'DAY'    THEN 86400
                                                                                              ELSE 60
                                                          END AS SETUP_TIME_03,
                               ISNULL(H.SETUP_TIME, 0) *  CASE H.SETUP_TIME_UOM WHEN 'SECOND' THEN 1
                                                                                WHEN 'MINUTE' THEN 60
                         WHEN 'HOUR'   THEN 3600
                                                                                WHEN 'DAY'    THEN 86400
                                                                                              ELSE 60
                                                          END AS SETUP_TIME_04
                        FROM   (
                                SELECT A.*, D.SETUP_GROUP_ID AS FROM_SETUP_GROUP_ID
                                FROM   (
                                        SELECT A.MASTER_ID, A.PLAN_ID,
                                               A.WORK_ORDER_ID, A.AFTER_SITE_ID, A.AFTER_ROUTE_ID, A.AFTER_OPERATION_ID, A.AFTER_RESOURCE_ID, A.AFTER_PLAN_DATE, A.AFTER_SEQ, 
                                               B.RESOURCE_SETUP_GROUP_ID,
                                               A.ITEM_ID, C.SETUP_GROUP_ID TO_SETUP_GROUP_ID,
                                               LAG(A.ITEM_ID, 1, NULL) OVER (PARTITION BY A.AFTER_SITE_ID, A.AFTER_ROUTE_ID, A.AFTER_OPERATION_ID, A.AFTER_RESOURCE_ID, A.AFTER_PLAN_DATE
                                                                             ORDER     BY A.AFTER_SEQ, A.WORK_ORDER_ID) AS BEFORE_ITEM_ID
                                        FROM   SY_FP_AMEND_PRODUCTION_PLAN_R A,
                                               SY_FP_AMEND_RESOURCE B,
                                               SY_FP_AMEND_ITEM_OPERATION C
                                        WHERE  A.MASTER_ID          = @v_master_id
                                        AND    A.PLAN_ID            = @v_plan_id
                                        AND    A.MASTER_ID          = B.MASTER_ID
                                        AND    A.PLAN_ID            = B.PLAN_ID
                                        AND    A.AFTER_RESOURCE_ID  = B.RESOURCE_ID 
                                        AND    A.MASTER_ID          = C.MASTER_ID
                                        AND    A.PLAN_ID            = C.PLAN_ID
                                        AND    A.ITEM_ID            = C.ITEM_ID
                                        AND    A.AFTER_OPERATION_ID = C.OPERATION_ID
                                       ) A
                                       LEFT OUTER JOIN SY_FP_AMEND_ITEM_OPERATION D
                                            ON    A.MASTER_ID           = D.MASTER_ID
                                            AND   A.PLAN_ID             = D.PLAN_ID
                                            AND   A.BEFORE_ITEM_ID      = D.ITEM_ID
                                            AND   A.AFTER_OPERATION_ID  = D.OPERATION_ID
                               ) A
                               LEFT OUTER JOIN SY_FP_AMEND_SETUP_MATRIX E
                                    ON    A.MASTER_ID               = E.MASTER_ID
                                    AND   A.PLAN_ID                 = E.PLAN_ID
                                    AND   A.RESOURCE_SETUP_GROUP_ID = E.RESOURCE_SETUP_GROUP_ID
                                    AND   A.FROM_SETUP_GROUP_ID     = E.FROM_SETUP_GROUP_ID
                                    AND   A.TO_SETUP_GROUP_ID       = E.TO_SETUP_GROUP_ID
                               LEFT OUTER JOIN SY_FP_AMEND_SETUP_MATRIX F
                                    ON    A.MASTER_ID               = F.MASTER_ID
                                    AND   A.PLAN_ID                 = F.PLAN_ID
                                    AND   A.RESOURCE_SETUP_GROUP_ID = F.RESOURCE_SETUP_GROUP_ID
                                    AND   A.FROM_SETUP_GROUP_ID    != A.TO_SETUP_GROUP_ID
                                    AND   F.FROM_SETUP_GROUP_ID     = 'ALL'
                                    AND   A.TO_SETUP_GROUP_ID       = F.TO_SETUP_GROUP_ID
                               LEFT OUTER JOIN SY_FP_AMEND_SETUP_MATRIX G
                                    ON    A.MASTER_ID               = G.MASTER_ID
                                    AND   A.PLAN_ID                 = G.PLAN_ID
                                    AND   A.RESOURCE_SETUP_GROUP_ID = G.RESOURCE_SETUP_GROUP_ID
                                    AND   A.FROM_SETUP_GROUP_ID    != A.TO_SETUP_GROUP_ID
                                    AND   A.FROM_SETUP_GROUP_ID     = G.FROM_SETUP_GROUP_ID
                                    AND   G.TO_SETUP_GROUP_ID       = 'ALL'
                               LEFT OUTER JOIN SY_FP_AMEND_SETUP_MATRIX H
                                    ON    A.MASTER_ID               = H.MASTER_ID
                                    AND   A.PLAN_ID                 = H.PLAN_ID
                                    AND   A.RESOURCE_SETUP_GROUP_ID = H.RESOURCE_SETUP_GROUP_ID
                                    AND   A.FROM_SETUP_GROUP_ID    != A.TO_SETUP_GROUP_ID
                                    AND   H.FROM_SETUP_GROUP_ID     = 'ALL'
                                    AND   H.TO_SETUP_GROUP_ID       = 'ALL'
                       ) A
               ) B
        WHERE  B.SETUP_TIME > 0
        AND    A.MASTER_ID          = @v_master_id
        AND    A.PLAN_ID            = @v_plan_id
        AND    A.WORK_ORDER_ID      = B.WORK_ORDER_ID
        AND    A.AFTER_SITE_ID      = B.AFTER_SITE_ID
        AND    A.AFTER_ROUTE_ID     = B.AFTER_ROUTE_ID
        AND    A.AFTER_OPERATION_ID = B.AFTER_OPERATION_ID
        AND    A.AFTER_PLAN_DATE    = B.AFTER_PLAN_DATE
        AND    A.AFTER_SEQ          = B.AFTER_SEQ
      
        SET @v_message = 'SETUP_TIME : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null
      
        -- TOP_WORK_ORDER_ID 추가
        UPDATE  SY_FP_AMEND_PRODUCTION_PLAN_R
        SET     SY_FP_AMEND_PRODUCTION_PLAN_R.TOP_WORK_ORDER_ID = B.TOP_WORK_ORDER_ID
        FROM    SY_FP_AMEND_PRODUCTION_PLAN_R A,
                SY_FP_PRODUCTION_PLAN_EQUIPMENT_R B
        WHERE   A.MASTER_ID         = B.INSTANCE_ID
        AND     A.PLAN_ID           = B.FP_PLAN_ID
        AND     A.ORG_WORK_ORDER_ID = B.WORK_ORDER_ID
        AND     A.MASTER_ID         = @v_master_id
        AND     A.PLAN_ID           = @v_plan_id
          
        SET @v_message = 'TOP_WORK_ORDER_ID : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null
      
      END

