             , TOP_ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , PLAN_DATE
             , RUN_TIME
             , RUN_TIME_UOM
             , PLAN_QTY
             , PLAN_IN_QTY
             , ITEM_UOM
             , PRODUCTION_TYPE
             , RESULT_TYPE
             , LINE_ITEM_SEQ
             , OPERATION_ITEM_SEQ
             , INSERT_ID
             , INSERT_TIME
             )
        SELECT 
               B.MASTER_ID    AS INSTANCE_ID
             , B.PLAN_ID      AS FP_PLAN_ID
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.ITEM_ID
             , A.ITEM_ID      AS TOP_ITEM_ID
             , A.OPERATION_ID
             , ISNULL(A.LINE_ID, '-') AS LINE_ID
             , '-'  AS ELECTRODE_TYPE --D.ELECTRODE_TYPE
             , CONVERT(DATE, PRODUCT_DATE) AS PLAN_DATE
             , 0 AS RUN_TIME
             , 'SECOND' RUN_TIME_UOM
             , CEILING(SUM(ISNULL(A.WIPQTY2_ENGINE,0))) AS PLAN_QTY
             , CEILING(SUM(ISNULL(A.QTY_LANE,0))) AS PLAN_IN_QTY
             , E.ITEM_UOM
             , CASE WHEN A.PRODUCTION_TYPE IS NULL THEN 'MASS'
                    WHEN A.PRODUCTION_TYPE = ''    THEN 'MASS'
                    ELSE A.PRODUCTION_TYPE
               END  AS PRODUCTION_TYPE
             , 'Y'                                AS RESULT_TYPE    -- 실적 계획
             , 9999                               AS LINE_ITEM_SEQ
             , 9999                               AS OPERATION_ITEM_SEQ
             , @v_proc_name                       AS INSERT_ID
             , GETDATE()                          AS INSERT_TIME
        FROM   SY_SCM_PRODUCT_RESULT_H A,
               (
                SELECT DISTINCT A.MASTER_ID, A.PLAN_ID,
                       A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.ITEM_ID, A.OPERATION_ID
                FROM   TH_MST_INSTANCE_FLOW A,
                       SY_SCM_OPERATION_M   B
                WHERE  A.MASTER_ID    = @v_master_id
                AND    A.PLAN_ID      = @v_plan_id
                AND    A.COMPANY_ID   = B.COMPANY_ID
                AND    A.DIVISION_ID  = B.DIVISION_ID
                AND    A.SITE_ID      = B.SITE_ID
                AND    A.OPERATION_ID = B.OPERATION_ID
                --AND    B.AMEND_FLAG   = 'Y'
               ) B,
               (
              SELECT B.DATE_ID
                FROM   TH_MST_PLAN A,
                       SY_SCM_SYS_CALENDAR_M B
                WHERE  A.MASTER_ID  = @v_master_id
                AND    A.PLAN_ID    = @v_plan_id
                AND    A.WEEK       = B.WEEK
                AND    B.DATE_ID    < CONVERT(DATE, A.PLAN_START_DTTM)  -- 당일 PLAN_DATE 보다 과거 실적
               ) C,
               --SY_SCM_LINE_M D,
               SY_SCM_ITEM_M  E
        WHERE  A.COMPANY_ID   = B.COMPANY_ID
        AND    A.DIVISION_ID  = B.DIVISION_ID
        AND    A.SITE_ID      = B.SITE_ID
        AND    A.ITEM_ID      = B.ITEM_ID
        AND    A.CUTOFF_DATE  = C.DATE_ID 
        --AND    A.COMPANY_ID   = D.COMPANY_ID
        --AND    A.DIVISION_ID  = D.DIVISION_ID
        --AND    A.SITE_ID      = D.SITE_ID
        --AND    A.PLANT_ID     = D.PLANT_ID
        --AND    A.FACTORY_ID   = D.FACTORY_ID
        --AND    A.LINE_ID      = D.LINE_ID
        --AND    A.OPERATION_ID = D.OPERATION_ID
        AND    A.COMPANY_ID   = E.COMPANY_ID
        AND    A.DIVISION_ID  = E.DIVISION_ID
        AND    A.SITE_ID      = E.SITE_ID
        AND    A.ITEM_ID      = E.ITEM_ID
        GROUP  BY
               B.MASTER_ID
             , B.PLAN_ID
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.ITEM_ID
             , A.ITEM_ID
             , A.OPERATION_ID
             , ISNULL(A.LINE_ID, '-')
             --, D.ELECTRODE_TYPE
             , CONVERT(DATE, PRODUCT_DATE)
             , E.ITEM_UOM
             , CASE WHEN A.PRODUCTION_TYPE IS NULL THEN 'MASS'
                    WHEN A.PRODUCTION_TYPE = ''    THEN 'MASS'
                    ELSE A.PRODUCTION_TYPE
               END
        
        

        SET @v_message = 'RESULT : ' + CONVERT(nvarchar, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null


      END
*/      
    
      /*** FP_AMEND_LOB_PLAN_R 생성 ***/
      -- 2017.05.30 멈춤현상 발생 : BUFFER 테이블 사용하여 처리
/*        
      BEGIN

        SET @v_table_name = 'TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY'

        DELETE FROM TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY
        WHERE  INSERT_TIME < DATEADD(DAY, 7, GETDATE())
        
        DELETE FROM TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY
        WHERE  INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID  = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null
        
        INSERT INTO TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY
              (
                INSTANCE_ID
              , FP_PLAN_ID
              , COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , PRODUCTION_TYPE
              , CATEGORY_ID
              , PLAN_DATE
              , QTY
              , INSERT_TIME
              )
        SELECT B.MASTER_ID    AS INSTANCE_ID
             , B.PLAN_ID      AS FP_PLAN_ID
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.ITEM_ID
             , A.OPERATION_ID
             , CASE WHEN A.PRODUCTION_TYPE IS NULL THEN 'MASS'
                    WHEN A.PRODUCTION_TYPE = ''    THEN 'MASS'
                    ELSE A.PRODUCTION_TYPE
               END  AS PRODUCTION_TYPE
             , 'RESULT'  AS CATEGORY_ID        -- 실적
             , CONVERT(DATE, PRODUCT_DATE) AS PLAN_DATE         -- 과거 실적 데이터
             , ISNULL(A.WIPQTY2_ENGINE,0) AS QTY
             , GETDATE()        AS INSERT_TIME
        FROM   SY_SCM_PRODUCT_RESULT_H A,
               (
                SELECT A.MASTER_ID, A.PLAN_ID, B.DATE_ID
                FROM   TH_MST_PLAN A,
                       SY_SCM_SYS_CALENDAR_M B
                WHERE  A.MASTER_ID  = @v_master_id
                AND    A.PLAN_ID    = @v_plan_id
                AND    A.WEEK       = B.WEEK
                AND    B.DATE_ID    < CONVERT(DATE, A.PLAN_START_DTTM)  -- 당일 PLAN_DATE 보다 과거 실적
               ) B
        WHERE  A.CUTOFF_DATE  = B.DATE_ID 
        AND    EXISTS (
                        SELECT 1
                        FROM   (
                                SELECT DISTINCT
                                       A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.OPERATION_ID
                                FROM   SY_SCM_OPERATION_M       A,
                                       SY_FP_INSTANCE_FACTORY_M B,
                                       SY_SCM_FACTORY_M         C
                                WHERE  B.INSTANCE_ID    = @v_master_id
                                AND    A.COMPANY_ID     = C.COMPANY_ID
                                AND    A.DIVISION_ID    = C.DIVISION_ID
                                AND    A.SITE_ID        = C.SITE_ID
                                AND    A.INSTANCE_TYPE  = B.INSTANCE_TYPE
                                AND    B.FACTORY_ID     = C.FACTORY_ID
                               ) X
                        WHERE  X.COMPANY_ID   = A.COMPANY_ID
                        AND    X.DIVISION_ID  = A.DIVISION_ID
                        AND    X.SITE_ID      = A.SITE_ID
                        AND    X.OPERATION_ID = A.OPERATION_ID
                      )        
        

        SET @v_message = 'RESULT : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null


        INSERT INTO TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY
              (
                INSTANCE_ID
              , FP_PLAN_ID
              , COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , PRODUCTION_TYPE
              , CATEGORY_ID
              , PLAN_DATE
              , QTY
              , INSERT_TIME
              )
        SELECT A.MASTER_ID AS INSTANCE_ID
             , A.PLAN_ID    AS FP_PLAN_ID
             , B.COMPANY_ID
             , B.DIVISION_ID
             , B.SITE_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , A.ITEM_ID
             , A.OPERATION_ID
             , CASE WHEN A.PRODUCTION_TYPE IS NULL THEN 'MASS'
                    WHEN A.PRODUCTION_TYPE = ''    THEN 'MASS'
                    ELSE A.PRODUCTION_TYPE
               END  AS PRODUCTION_TYPE
             , 'STOCK'  AS CATEGORY_ID        -- STOCK
             , CONVERT(DATE, @v_plan_start_date) AS PLAN_DATE
             , A.QTY
             , GETDATE()        AS INSERT_TIME
        FROM   --TH_MST_STOCK_PLAN A,
               (
                SELECT A.MASTER_ID
                     , A.PLAN_ID
                     , A.ITEM_ID
                     , A.SITE_ID
                     , A.OPERATION_ID
                     , A.PRODUCTION_TYPE
                     , CASE WHEN A.QTY > ISNULL(B.SUM_QTY, A.QTY) THEN A.QTY
                            ELSE ISNULL(B.SUM_QTY, A.QTY)
                       END  QTY
                FROM   (
                        SELECT A.MASTER_ID
                             , A.PLAN_ID
                             , A.ITEM_ID
                             , A.SITE_ID
                             , A.OPERATION_ID
                             , A.STOCK_ATTB_1   AS PRODUCTION_TYPE
                             , A.QTY
                             , B.LOT_ID
                        FROM   TH_MST_STOCK_PLAN A,
                               TH_ENG_STOCK_PLAN B
                        WHERE  A.MASTER_ID  = @v_master_id
                        AND    A.PLAN_ID    = @v_plan_id
                        AND    A.MASTER_ID  = B.MASTER_ID
                        AND    A.PLAN_ID    = B.PLAN_ID
                        AND    A.LOT_ID     = B.LOT_ID
                        AND    A.OPERATION_ID != '-'
                        AND    EXISTS (
                                        SELECT 1
                                        FROM   (
                                                SELECT DISTINCT
                                                       A.OPERATION_ID
                                                FROM   SY_SCM_OPERATION_M       A,
                                                       SY_FP_INSTANCE_FACTORY_M B,
                                                       SY_SCM_FACTORY_M         C
                                                WHERE  B.INSTANCE_ID    = @v_master_id
                                                AND    A.COMPANY_ID     = C.COMPANY_ID
                                                AND    A.DIVISION_ID    = C.DIVISION_ID
                                                AND    A.SITE_ID        = C.SITE_ID
                                                AND    A.INSTANCE_TYPE  = B.INSTANCE_TYPE
                                                AND    B.FACTORY_ID     = C.FACTORY_ID
                                               ) X
                                        WHERE  X.OPERATION_ID = A.OPERATION_ID
                                      )
               ) A
               LEFT OUTER JOIN (
                                SELECT FROM_STOCK_SET_ID, SUM(QTY) AS SUM_QTY
                                FROM   (
                                        SELECT DISTINCT A.FROM_STOCK_SET_ID,
                                               CEILING(FROM_QTY) AS QTY
                                        FROM   SY_FP_ORDER_PEGGING_R A
                                        WHERE  A.INSTANCE_ID = @v_master_id
                                        AND    A.FP_PLAN_ID  = @v_plan_id
                                        AND    A.FROM_STOCK_SET_ID != '-'
                                        AND    A.FROM_OPERATION_ID != '-'
                                       ) A
                               GROUP  BY FROM_STOCK_SET_ID       
                               ) B
                          ON   A.LOT_ID = B.FROM_STOCK_SET_iD
               ) A,
               SY_SCM_FACTORY_M B
        WHERE  A.MASTER_ID    = @v_master_id
        AND    A.PLAN_ID      = @v_plan_id
        AND    A.SITE_ID      = B.FACTORY_ID
        AND    A.OPERATION_ID IS NOT NULL

        SET @v_message = 'STOCK : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null


        INSERT INTO TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY
              (
                INSTANCE_ID
              , FP_PLAN_ID
              , COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , PRODUCTION_TYPE
              , CATEGORY_ID
              , PLAN_DATE
              , QTY
              , INSERT_TIME
              )
        SELECT A.INSTANCE_ID
             , A.FP_PLAN_ID
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FROM_FACTORY_ID    AS FACTORY_ID
             , A.FROM_ITEM_ID       AS ITEM_ID
             , A.FROM_OPERATION_ID  AS OPERATION_ID
             , CASE WHEN A.PRODUCTION_TYPE IS NULL THEN 'MASS'
                    WHEN A.PRODUCTION_TYPE = ''    THEN 'MASS'
                    ELSE A.PRODUCTION_TYPE
               END  AS PRODUCTION_TYPE
             , 'STOCK_DEMAND'       AS CATEGORY_ID
             , CONVERT(DATE, A.AFTER_PLAN_DATE) AS PLAN_DATE
             , CASE WHEN SEQ = 1 THEN QTY - SUM_QTY + RATE_QTY
                                 ELSE RATE_QTY
               END  NEW_QTY                
             , GETDATE()        AS INSERT_TIME
        FROM   (
                SELECT A.*
                     , SUM(RATE_QTY) OVER (PARTITION BY FROM_STOCK_SET_ID, TO_WORK_ORDER_ID) SUM_QTY
                FROM   (
                        SELECT A.*,
                               FLOOR(QTY * (AFTER_QTY /TO_WORK_SUM_QTY)) AS RATE_QTY
                        FROM   (
                                SELECT A.*,
                                       B.DEMAND_TYPE AS PRODUCTION_TYPE,
                                       B.AFTER_PLAN_DATE,
                                       B.AFTER_QTY,
                                       DENSE_RANK()   OVER (PARTITION BY FROM_STOCK_SET_ID, TO_WORK_ORDER_ID ORDER BY AFTER_PLAN_DATE DESC) AS SEQ,
                                       SUM(AFTER_QTY) OVER (PARTITION BY FROM_STOCK_SET_ID, TO_WORK_ORDER_ID) AS TO_WORK_SUM_QTY
                                FROM   (
                                        SELECT A.*
                                             , SUM(QTY) OVER (PARTITION BY FROM_STOCK_SET_ID) AS STOCK_QTY
                                        FROM   (
                                                SELECT A.INSTANCE_ID, A.FP_PLAN_ID, 
                                                       A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FROM_FACTORY_ID, A.FROM_ITEM_ID, A.FROM_OPERATION_ID,
                                                       A.FROM_STOCK_SET_ID, A.TO_WORK_ORDER_ID,
                                                       CEILING(FROM_QTY) AS QTY
                                                FROM   SY_FP_ORDER_PEGGING_R A
                                                WHERE  A.INSTANCE_ID = @v_master_id
                                                AND    A.FP_PLAN_ID  = @v_plan_id
                                                AND    A.FROM_STOCK_SET_ID != '-'
                                                AND    A.FROM_OPERATION_ID != '-'
                                                AND    EXISTS (
                                                                SELECT 1
                                                                FROM   (
                                                                        SELECT DISTINCT
                                                                               A.OPERATION_ID
                                                                        FROM   SY_SCM_OPERATION_M       A,
                                                                               SY_FP_INSTANCE_FACTORY_M B,
                                                                               SY_SCM_FACTORY_M         C
                                                                        WHERE  B.INSTANCE_ID    = @v_master_id
                                                                        AND    A.COMPANY_ID     = C.COMPANY_ID
                                                                        AND    A.DIVISION_ID    = C.DIVISION_ID
                                                                        AND    A.SITE_ID        = C.SITE_ID
                                                                        AND    A.INSTANCE_TYPE  = B.INSTANCE_TYPE
                                                                        AND    B.FACTORY_ID     = C.FACTORY_ID
                                                                       ) X
         WHERE  X.OPERATION_ID = A.FROM_OPERATION_ID
                                                              )
                                               ) A
                                       ) A,
                                       SY_FP_AMEND_PRODUCTION_PLAN_R B
                                WHERE  A.INSTANCE_ID = B.MASTER_ID
                                AND    A.FP_PLAN_ID = B.PLAN_ID
                                AND    A.TO_WORK_ORDER_ID = B.ORG_WORK_ORDER_ID
                               ) A
                       ) A
               ) A
        
        SET @v_message = 'STOCK_DEMAND : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null


        UPDATE TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY
        SET    TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.ITEM_UOM         = B.ITEM_UOM
             , TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.ITEM_CLASS       = B.ITEM_CLASS
             , TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.COATED_LENGTH    = B.COATED_LENGTH
             , TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.UNCOATED_LENGTH  = B.UNCOATED_LENGTH
             , TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.LENGTH_UOM       = B.LENGTH_UOM
        FROM   TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY  A,
               SY_SCM_ITEM_M                      B
        WHERE  A.INSTANCE_ID  = @v_master_id
        AND    A.FP_PLAN_ID   = @v_plan_id
        AND    A.COMPANY_ID   = B.COMPANY_ID
        AND    A.DIVISION_ID  = B.DIVISION_ID
        AND    A.SITE_ID      = B.SITE_ID
        AND    A.ITEM_ID      = B.ITEM_ID

        SET @v_message = 'ITEM_UOM, ITEM_CLASS, ...LENGTH : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null


        UPDATE TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY
        SET    TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.ROLL_QTY =  (CASE WHEN UPPER(A.ITEM_UOM) = 'M'
                                                                   THEN A.QTY -- Pancake
                                                                   WHEN UPPER(A.ITEM_UOM) != 'M'
                                                                   THEN A.QTY -- Pancake
                                                                        / ISNULL(D.PATTERN_QTY,1) 
                                                                        * (CASE WHEN (ISNULL(A.COATED_LENGTH,0) + ISNULL(A.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                ELSE (ISNULL(A.COATED_LENGTH,0) + ISNULL(A.UNCOATED_LENGTH, 0)) 
                                                                                        / (CASE UPPER(A.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                                                    WHEN 'CM' THEN 100
                                                                                                                    WHEN 'MM' THEN 1000
                                                                                                                              ELSE 1 END)
                                                                          END )
                                                                    ELSE NULL END)
             , TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.JR_QTY   =   (CASE WHEN UPPER(A.ITEM_UOM) = 'M'
                                                                    THEN A.QTY / D.LANE_QTY -- Roll 
                                                                    WHEN UPPER(A.ITEM_UOM) != 'M'
                                                                    THEN A.QTY / D.LANE_QTY -- Roll
                                                                       / ISNULL(D.PATTERN_QTY,1) 
                                                                          * (CASE WHEN (ISNULL(A.COATED_LENGTH,0) + ISNULL(A.UNCOATED_LENGTH, 0)) = 0 THEN 1
                                                                                  ELSE (ISNULL(A.COATED_LENGTH,0) + ISNULL(A.UNCOATED_LENGTH, 0)) 
                                                                                          / (CASE UPPER(A.LENGTH_UOM) WHEN 'M'  THEN 1
                                                                                                                      WHEN 'CM' THEN 100
                                                                                                                      WHEN 'MM' THEN 1000
                                                                                                                                ELSE 1 END)
                                                                            END )
                                                                    ELSE NULL END)
             , TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY.CELL_QTY =   (CASE WHEN @v_master_id LIKE '%PMIX' THEN NULL
                                                                    WHEN  E.ACCUMULATED_CHILD_QTY IS NULL THEN NULL 
                                                                    ELSE  A.QTY / (CASE WHEN E.ACCUMULATED_CHILD_QTY = 0 THEN 1 
                                                                                             ELSE E.ACCUMULATED_CHILD_QTY END)
                                                                    END)
          FROM   TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY A
                 LEFT OUTER JOIN SY_SCM_ITEM_CLASS_M C
                      ON    A.ITEM_CLASS = C.CLASS_ID
                      AND   C.LEVEL_2_CODE = 'APC'
                 LEFT OUTER JOIN (
                                  SELECT DISTINCT COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, ITEM_ID, LANE_QTY, PATTERN_QTY
                                  FROM   (
                                          SELECT A.*,
                                                 DENSE_RANK() OVER (PARTITION BY COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, ITEM_ID
                                                                    ORDER     BY CASE WHEN ACTIVE_FLAG = 'Y'    THEN 1
                                                                                      WHEN ACTIVE_FLAG IS NULL  THEN 2
                                                                                      ELSE 3
                                                                                 END,
                                                                                 LANE_QTY DESC
                                                                               , FACTORY_ID
                                                                               , MAIN_LANE_QTY DESC
                                                                               , SUB_LANE_QTY
                                                                               , PATTERN_QTY) AS SEQ
                                          FROM   SY_SCM_ITEM_LANE_M A
                                         ) A
                                  WHERE  SEQ = 1       
                                 ) D
                      ON    A.COMPANY_ID = D.COMPANY_ID
                      AND   A.DIVISION_ID = D.DIVISION_ID
                      AND   A.SITE_ID = D.SITE_ID
                      AND   A.PLANT_ID = D.PLANT_ID
                      AND   A.FACTORY_ID = D.FACTORY_ID
                      AND   A.ITEM_ID = D.ITEM_ID
                 LEFT OUTER JOIN SY_FP_ITEM_CELL_EXCHANGE_M E
                      ON      A.ITEM_ID = E.ITEM_ID
                      AND     A.DIVISION_ID = E.DIVISION_ID
        WHERE  INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID  = @v_plan_id

        SET @v_message = 'ROLL_QTY, JR_QTY, CELL_QTY : ' + CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'UPDATE', @n_log_count, null, @v_message, null


        SET @v_table_name = 'FP_AMEND_LOB_PSI_CATEGORY_R'
        
        DELETE FROM SY_FP_AMEND_LOB_PSI_CATEGORY_R
        WHERE  INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID  = @v_plan_id

        --LOG 생성
        SET @v_message = @@ROWCOUNT
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'DELETE', @n_log_count, null, @v_message, null

        INSERT INTO SY_FP_AMEND_LOB_PSI_CATEGORY_R
             (
               INSTANCE_ID
             , FP_PLAN_ID
             , COMPANY_ID
             , DIVISION_ID
             , SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , PRODUCTION_TYPE
             , CATEGORY_ID        
             , PLAN_DATE
             , QTY
             , ROLL_QTY
             , JR_QTY
             , CELL_QTY
             , ITEM_UOM
             , OPERATION_ITEM_SEQ
             , INSERT_ID
             , INSERT_TIME
             )
        SELECT A.INSTANCE_ID
             , A.FP_pLAN_ID
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.ITEM_ID 
             , A.OPERATION_ID
             , A.PRODUCTION_TYPE
             , A.CATEGORY_ID
             , CONVERT(DATE, A.PLAN_DATE) AS PLAN_DATE
             , SUM(QTY)                   AS QTY
             , SUM(ROLL_QTY)              AS ROLL_QTY
             , SUM(JR_QTY)                AS JR_QTY
             , SUM(CEILING(CELL_QTY))     AS CELL_QTY
             , MAX(A.ITEM_UOM)            AS ITEM_UOM
             , 9999 AS OPERATION_ITEM_SEQ
             , @v_proc_name AS INSERT_ID
             , GETDATE()    AS INSERT_TIME
        FROM   TH_BUF_SCM_AMEND_LOB_PSI_CATEGORY A
        WHERE  INSTANCE_ID = @v_master_id
        AND    FP_PLAN_ID  = @v_plan_id
        GROUP  BY
               A.INSTANCE_ID
             , A.FP_pLAN_ID
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.ITEM_ID 
             , A.OPERATION_ID
             , A.PRODUCTION_TYPE
             , A.CATEGORY_ID
             , CONVERT(DATE, A.PLAN_DATE)        

        SET @v_message = CONVERT(NVARCHAR, @@ROWCOUNT)
        SET @n_log_count = @n_log_count + 1
        SET @sysdate = GETDATE()
        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, @v_table_name, 'INSERT', @n_log_count, null, @v_message, null
             
        -------------------------------------------------------------------------------------------------------------------

      END
*/
      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, null, 'END', 999999, null, '=============== End of procedure ===============', null

    END TRY

    BEGIN CATCH
      BEGIN

        DECLARE 
          @v_error_message nvarchar(max),
          @v_error_procedure nvarchar(max),
          @v_error_line nvarchar(max)

        SET @v_error_message = ERROR_MESSAGE()

        SET @v_error_procedure = ERROR_PROCEDURE()

        SET @v_error_line = convert(nvarchar,ERROR_LINE())


        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_error_procedure, null, 'ERROR', null, @v_error_line, null, @v_error_message

        IF @@TRANCOUNT > 0
           COMMIT WORK 
      END
    END CATCH
END
